        summary['independent_absence'][label]={'code':actual,'observed_ms':rows[label]['response_observed_ms']}
    for label in ('verify-owned-bucket-versions-empty','verify-owned-bucket-objects-empty'):
        out=rows[label]['result']['output']; assert not out.get('Versions') and not out.get('DeleteMarkers') and not out.get('Contents'),label
